/**
 * Requests jobs
 * Requests response generated by a tool run
 */

import { defineStore } from "pinia";
import { ref } from "vue";

import { GalaxyApi } from "@/api";
import { fetchJobs, type JobBaseModel, type ResponseVal, type ShowFullJobResponse, TERMINAL_STATES } from "@/api/jobs";
import { type FetchParams, useKeyedCache } from "@/composables/keyedCache";
import { rethrowSimpleWithStatus } from "@/utils/simple-error";

export const useJobStore = defineStore("jobStore", () => {
    const latestResponse = ref<ResponseVal | null>(null);
    const allJobs = ref<JobBaseModel[]>([]);

    /**
     * Fetch a page of jobs and store them.
     * @param offset Return jobs starting from this position
     * @param limit Maximum number of jobs to return
     * @param extraProps Additional filters
     * @returns The fetched page of jobs
     */
    async function fetchAllJobs(offset = 0, limit = 20, extraProps?: Record<string, unknown>) {
        const jobs = await fetchJobs(offset, limit, extraProps);
        jobs.forEach(storeJob);
        return jobs;
    }

    function storeJob(job: JobBaseModel) {
        const index = allJobs.value.findIndex((storedJob) => storedJob.id === job.id);
        if (index >= 0) {
            allJobs.value.splice(index, 1, job);
        } else {
            allJobs.value.push(job);
        }
    }

    async function fetchJobById(params: FetchParams): Promise<ShowFullJobResponse> {
        const { data, error, response } = await GalaxyApi().GET("/api/jobs/{job_id}", {
            params: { path: { job_id: params.id } },
            query: { full: true },
        });
        if (error) {
            rethrowSimpleWithStatus(error, response);
        }
        return data;
    }

    function saveLatestResponse(newResponse: ResponseVal) {
        latestResponse.value = newResponse;
    }

    const {
        fetchItemById: fetchJob,
        getItemById: getJob,
        getItemLoadError: getJobLoadError,
        isLoadingItem: isLoadingJob,
    } = useKeyedCache<ShowFullJobResponse>(fetchJobById);

    function pollJobUntilTerminal(params: FetchParams) {
        function poll() {
            fetchJob(params);
            setTimeout(pollJobUntilTerminal, 1000, params);
        }

        const job = getJob.value(params.id);
        if (job) {
            const jobState = job.state;
            if (TERMINAL_STATES.indexOf(jobState) !== -1) {
                return;
            } else {
                poll();
            }
        } else {
            poll();
        }
    }

    return {
        fetchJob,
        fetchAllJobs,
        allJobs,
        saveLatestResponse,
        getJob,
        getJobLoadError,
        isLoadingJob,
        latestResponse,
        pollJobUntilTerminal,
        storeJob,
    };
});
